"""Add synchronized completed document-processing results and source links."""
from alembic import op

revision = '0012_proc_document_jobs'
down_revision = '0011_proc_documents'
branch_labels = None
depends_on = None

SQL = "-- Current completed extraction results; no worker, model egress or read-path changes.\nCREATE TABLE public.proc_document_jobs (\n    tenant varchar(64) NOT NULL,\n    id varchar(64) NOT NULL,\n    source_revision integer NOT NULL CHECK(source_revision>=1),\n    document_id varchar(64) NOT NULL,\n    state text NOT NULL CHECK(state='completed'),\n    execution text NOT NULL CHECK(execution IN ('synchronous-bounded-graph','private-model-gateway')),\n    result jsonb NOT NULL CHECK(jsonb_typeof(result)='object'),\n    candidate_count integer NOT NULL CHECK(candidate_count>=0),\n    model_version text,\n    source_snapshot jsonb NOT NULL CHECK(jsonb_typeof(source_snapshot)='object'),\n    PRIMARY KEY(tenant,id),\n    FOREIGN KEY(tenant,id) REFERENCES public.records(tenant,id) DEFERRABLE INITIALLY DEFERRED,\n    FOREIGN KEY(tenant,document_id) REFERENCES public.proc_documents(tenant,id) DEFERRABLE INITIALLY DEFERRED,\n    CHECK(execution<>'private-model-gateway' OR (model_version IS NOT NULL AND length(model_version)>0))\n);\nCREATE INDEX ix_proc_document_jobs_document ON public.proc_document_jobs(tenant,document_id,execution);\nALTER TABLE public.proc_document_jobs ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.proc_document_jobs FORCE ROW LEVEL SECURITY;\nCREATE POLICY tenant_scope ON public.proc_document_jobs TO supplypilot_app\n    USING(tenant=NULLIF(current_setting('supplypilot.tenant',true),''))\n    WITH CHECK(tenant=NULLIF(current_setting('supplypilot.tenant',true),''));\nCREATE POLICY migration_owner ON public.proc_document_jobs TO supplypilot_migrator USING(true) WITH CHECK(true);\nREVOKE ALL ON TABLE public.proc_document_jobs FROM PUBLIC,supplypilot_app;\nGRANT SELECT ON TABLE public.proc_document_jobs TO supplypilot_app;\n\nCREATE FUNCTION public.sync_procurement_document_job()\nRETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp\nAS $$ DECLARE d jsonb; result_data jsonb; key text;\nBEGIN\n    IF TG_OP='UPDATE' AND (OLD.kind='job' OR NEW.kind='job') AND\n       (OLD.tenant,OLD.id,OLD.kind) IS DISTINCT FROM (NEW.tenant,NEW.id,NEW.kind) THEN\n        RAISE EXCEPTION 'Document job identity, tenant and kind are immutable' USING ERRCODE='23514';\n    END IF;\n    IF TG_OP='DELETE' THEN\n        IF OLD.kind='job' THEN DELETE FROM public.proc_document_jobs WHERE tenant=OLD.tenant AND id=OLD.id; END IF;\n        RETURN OLD;\n    END IF;\n    IF NEW.kind<>'job' THEN RETURN NEW; END IF;\n    IF TG_OP='UPDATE' AND OLD.kind='job' AND\n       (OLD.data->>'document_id',OLD.data->>'execution') IS DISTINCT FROM\n       (NEW.data->>'document_id',NEW.data->>'execution') THEN\n        RAISE EXCEPTION 'Completed job document and execution identity are immutable' USING ERRCODE='23514';\n    END IF;\n    d:=NEW.data::jsonb;result_data:=d->'result';\n    FOREACH key IN ARRAY ARRAY['document_id','state','execution'] LOOP\n        IF jsonb_typeof(d->key) IS DISTINCT FROM 'string' THEN\n            RAISE EXCEPTION 'Document job metadata must be strings' USING ERRCODE='23514';\n        END IF;\n    END LOOP;\n    IF jsonb_typeof(result_data) IS DISTINCT FROM 'object' OR\n       jsonb_typeof(result_data->'candidates') IS DISTINCT FROM 'array' THEN\n        RAISE EXCEPTION 'Document job result requires an object with candidate array' USING ERRCODE='23514';\n    END IF;\n    IF EXISTS(SELECT 1 FROM jsonb_array_elements(result_data->'candidates') AS c(value)\n              WHERE jsonb_typeof(c.value)<>'object') THEN\n        RAISE EXCEPTION 'Document extraction candidates must be objects' USING ERRCODE='23514';\n    END IF;\n    IF result_data ? 'model_version' AND result_data->'model_version'<>'null'::jsonb AND\n       jsonb_typeof(result_data->'model_version')<>'string' THEN\n        RAISE EXCEPTION 'Model version must be string or null' USING ERRCODE='23514';\n    END IF;\n    INSERT INTO public.proc_document_jobs VALUES(NEW.tenant,NEW.id,NEW.revision,d->>'document_id',\n        d->>'state',d->>'execution',result_data,jsonb_array_length(result_data->'candidates'),\n        result_data->>'model_version',d-'result')\n    ON CONFLICT(tenant,id) DO UPDATE SET source_revision=EXCLUDED.source_revision,\n        document_id=EXCLUDED.document_id,state=EXCLUDED.state,execution=EXCLUDED.execution,\n        result=EXCLUDED.result,candidate_count=EXCLUDED.candidate_count,\n        model_version=EXCLUDED.model_version,source_snapshot=EXCLUDED.source_snapshot;\n    RETURN NEW;\nEND $$;\nREVOKE ALL ON FUNCTION public.sync_procurement_document_job() FROM PUBLIC,supplypilot_app;\nCREATE TRIGGER records_document_job_sync AFTER INSERT OR UPDATE OR DELETE ON public.records\nFOR EACH ROW EXECUTE FUNCTION public.sync_procurement_document_job();\nUPDATE public.records SET data=data WHERE kind='job';\n"


def upgrade():
    op.execute(SQL)


def downgrade():
    raise RuntimeError('Restore a reviewed backup; automatic document-job projection removal is disabled.')
